#!/usr/bin/env bash
# GSZ step141 — Netflix engine STAGE 1 (foundation, no customer impact).
# Adds lib/nfMail.js (portal code reader) + lib/netflixGate.js (Phone/TV/Full
# tier filter) + tables nf_accounts, nf_assignments. Runs a READ-ONLY portal
# connectivity self-test. Nothing is wired into checkout or any page yet.
# Idempotent; restores new files on failure.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step141-$TS"; TMP=$(mktemp -d)
NEW=(lib/nfMail.js lib/netflixGate.js)
echo "==> step141: Netflix engine — Stage 1 (libs + tables)"
mkdir -p "$BK/lib"
NEWHAD=()
for f in "${NEW[@]}"; do if [ -f "$GSZ/$f" ]; then NEWHAD+=("$f"); cp "$GSZ/$f" "$BK/$f"; fi; done
echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; for f in "${NEW[@]}"; do keep=0; for h in "${NEWHAD[@]:-}"; do [ "$h" = "$f" ] && keep=1; done; if [ "$keep" = "1" ]; then cp "$BK/$f" "$GSZ/$f"; else rm -f "$GSZ/$f"; fi; done; echo "!! restored."; }
trap 'restore' ERR
echo "==> writing libs"; mkdir -p "$GSZ/lib"
echo "" | base64 -d > "$GSZ/lib/nfMail.js"
echo ""   | base64 -d > "$GSZ/lib/netflixGate.js"
echo ""    | base64 -d > "$TMP/m.js"
echo ""   | base64 -d > "$TMP/t.js"
echo "==> validating"; node --check "$GSZ/lib/nfMail.js"; node --check "$GSZ/lib/netflixGate.js"
echo "==> migrating db (create nf_accounts, nf_assignments)"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/m.js" )
echo "==> portal connectivity self-test (read-only)"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/t.js" ) || true
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step141 OK ✅  Stage 1 in place: nfMail + netflixGate libs and the nf_accounts / nf_assignments tables. No live behaviour changed yet. Next: Stage 2 (admin to load Netflix accounts) + Stage 3 (auto-assign on paid order) + Stage 4 (inline tiered code panel)."
